SINA_SMART["parasito-hydatidosis"] = {"lecture":"parasito-hydatidosis","title":"Hydatidosis (hydatid cyst)","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"parasito-hydatidosis:e0","text":"Echinococcus granulosus: adult in dog's intestine; larva forms the hydatid cyst.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"parasito-hydatidosis:e1","text":"Dog = definitive host; sheep = intermediate host; human = accidental dead end.","topic":"Epidemiology and cycle","sec":1,"importance":"core","highYield":"untested"},{"id":"parasito-hydatidosis:e2","text":"Infection: stroking dogs, eggs on vegetables/water.","topic":"Epidemiology and cycle","sec":1,"importance":"core","highYield":"untested"},{"id":"parasito-hydatidosis:e3","text":"Morocco: stray dogs, clandestine and festival slaughter, offal to dogs.","topic":"Epidemiology and cycle","sec":1,"importance":"core","highYield":"untested"},{"id":"parasito-hydatidosis:e4","text":"Cyst layers: pericyst (host), ectocyst, germinal endocyst (brood capsules).","topic":"The parasite and the cyst","sec":2,"importance":"core","highYield":"untested"},{"id":"parasito-hydatidosis:e5","text":"Liver 50-60%, lung 30-40%, kidney 1.5-5%.","topic":"Clinical picture","sec":3,"importance":"core","highYield":"untested"},{"id":"parasito-hydatidosis:e6","text":"Rupture → anaphylaxis or secondary echinococcosis; lung → vomica.","topic":"Clinical picture","sec":3,"importance":"core","highYield":"untested"},{"id":"parasito-hydatidosis:e7","text":"Ultrasound is key: WHO-IWGE CE1-CE5.","topic":"Diagnosis","sec":4,"importance":"core","highYield":"untested"},{"id":"parasito-hydatidosis:e8","text":"Serology: ELISA + HAI screen; Western blot 17 kDa confirms; negative doesn't exclude.","topic":"Diagnosis","sec":4,"importance":"core","highYield":"untested"},{"id":"parasito-hydatidosis:e10","text":"Prevention: deworm dogs with praziquantel, destroy offal.","topic":"Treatment and prevention","sec":5,"importance":"core","highYield":"untested"},{"id":"parasito-hydatidosis:e9","text":"Surgery (90% cure), PAIR, or albendazole; watch-and-wait for CE4-5.","topic":"Treatment and prevention","sec":5,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"gte5c9":"a","19zek6j":"a","l4z2fz":"a","b0kbv0":"a","1t46zin":"a","1hnszyk":"a","3vpvlr":"a","5jlgpv":"a","1mpoc93":"a","oexoll":"a","1r9ee1p":"a","1peapbv":"a","1aooazn":"a","1g6v4br":"a","1rmyvso":"a","pj1e1j":"a"},"mapCounts":{"verified":0,"auto":16,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"parasito-hydatidosis:e0":{"s":0,"u":["Echinococcus granulosus: adult in dog's intestine; larva forms the hydatid cyst.","Hydatidosis is a cosmopolitan, rural zoonosis : the development in humans and herbivores of the larva of a small tapeworm, Echinococcus granulosus , whose adult lives in the dog's intestine ."],"dp":[]},"parasito-hydatidosis:e1":{"s":1,"u":["Dog = definitive host; sheep = intermediate host; human = accidental dead end.","Humans : accidental intermediate hosts (dead end).","Herbivores (sheep): intermediate hosts."],"dp":[]},"parasito-hydatidosis:e2":{"s":1,"u":["Infection: stroking dogs, eggs on vegetables/water.","Humans are infected directly (licking, stroking dogs) or indirectly (water, fruit, vegetables contaminated by eggs).","Why so endemic in Morocco : traditional pastoral and nomadic herding, 1-3 untreated dogs per herd, dead animals left unburied, millions of dogs (many stray), dogs at souk slaughterhouses, clandestine and family slaughter (weddings, Eid al-Adha, moussems) with offal given to dogs, poor hand and vegetable hygiene (children)."],"dp":[]},"parasito-hydatidosis:e3":{"s":1,"u":["Morocco: stray dogs, clandestine and festival slaughter, offal to dogs.","Why so endemic in Morocco : traditional pastoral and nomadic herding, 1-3 untreated dogs per herd, dead animals left unburied, millions of dogs (many stray), dogs at souk slaughterhouses, clandestine and family slaughter (weddings, Eid al-Adha, moussems) with offal given to dogs, poor hand and vegetable hygiene (children)."],"dp":[{"h":"Why offal is the heart of the problem","t":"Dogs are infected only by eating organs containing hydatid cysts. Each time sheep liver or lungs from home, festival or clandestine slaughter are thrown to dogs, the cycle is renewed and thousands of eggs are spread onto pastures and gardens. Destroying offal and deworming dogs breaks the cycle at its most vulnerable point. Source: the lecture's epidemiology and prophylaxis slides."}]},"parasito-hydatidosis:e4":{"s":2,"u":["Cyst layers: pericyst (host), ectocyst, germinal endocyst (brood capsules).","From outside in: pericyst (adventitia) : host organ tissue compressed by the cyst, not parasitic; ectocyst (cuticle) : white acellular outer wall; endocyst (germinal layer) : thin fertile membrane producing brood capsules with protoscolices and secreting the hydatid fluid .","Hydatid cyst = hydatid + pericyst ."],"dp":[]},"parasito-hydatidosis:e5":{"s":3,"u":["Liver 50-60%, lung 30-40%, kidney 1.5-5%.","Lung (30-40%) : shorter latency; cough, haemoptysis, vomica (rupture into a bronchus), dyspnoea, pleurisy; infection (lung abscess); ' water-lily ' sign on imaging.","Kidney (1.5-5%) : mostly left; mass, pain, haematuria, hypertension, hydaturia ."],"dp":[]},"parasito-hydatidosis:e6":{"s":3,"u":["Rupture → anaphylaxis or secondary echinococcosis; lung → vomica.","Lung (30-40%) : shorter latency; cough, haemoptysis, vomica (rupture into a bronchus), dyspnoea, pleurisy; infection (lung abscess); ' water-lily ' sign on imaging.","Liver (50-60%) : latency 10-15 years, painless hepatomegaly, pain, digestive signs, fever; complications: compression of bile ducts or vessels, cracking or rupture (immediate allergy up to anaphylactic shock ; late secondary echinococcosis), infection (liver abscess), cholestatic jaundice ."],"dp":[{"h":"Why a ruptured cyst is dangerous twice over","t":"Hydatid fluid is full of parasite antigens; when a cyst ruptures, the sudden release can cause an anaphylactic reaction. And the protoscolices it contains are alive: each one can grow into a new cyst wherever it lands, causing secondary echinococcosis. That is why surgeons sterilise the cyst before opening it and give albendazole around the procedure. Source: the lecture's cyst structure and complications slides."}]},"parasito-hydatidosis:e7":{"s":4,"u":["Ultrasound is key: WHO-IWGE CE1-CE5.","Imaging : ultrasound is the key test and guides treatment, using the WHO-IWGE classification : CL, CE1 (simple unilocular), CE2 (multivesicular, 'honeycomb/rosette'), CE3 (detached membranes ± daughter cysts), CE4 (degenerative, 'ball of wool'), CE5 (calcified); chest X-ray, CT, MRI for number and size."],"dp":[]},"parasito-hydatidosis:e8":{"s":4,"u":["Serology: ELISA + HAI screen; Western blot 17 kDa confirms; negative doesn't exclude.","Serology (a negative result does not exclude it, e.g. calcified cysts): screening with ELISA + haemagglutination (> 85%), confirmation by Western blot ( 17 kDa band specific to E. granulosus ); follow-up by ELISA: titres rise 4-6 weeks after surgery then become negative in 12-24 months; persistence or reappearance suggests recurrence (control every 3 months for 2 years, then every 6 months)."],"dp":[]},"parasito-hydatidosis:e10":{"s":5,"u":["Prevention: deworm dogs with praziquantel, destroy offal.","Prevention : veterinary slaughter control, incinerate offal , no clandestine slaughter; keep dogs out of slaughterhouses and deworm dogs with praziquantel ; hand washing, wash raw vegetables, keep dogs away from food; screening; a recombinant vaccine protects animals (95%)."],"dp":[]},"parasito-hydatidosis:e9":{"s":5,"u":["Surgery (90% cure), PAIR, or albendazole; watch-and-wait for CE4-5.","Albendazole alone for small ( Watch and wait for inactive CE4-CE5 cysts.","By stage: CE1/CE3a ≤ 10 cm → PAIR; > 10 cm → drainage; CE2/CE3b → surgery; complicated cysts → drainage or surgery."],"dp":[]}},"meta":{"gte5c9":{"a":"recall","vg":"parasito-hydatidosis:e0/recall/1"},"19zek6j":{"a":"recall","vg":"parasito-hydatidosis:e1/recall/1"},"l4z2fz":{"a":"recall","vg":"parasito-hydatidosis:e2/recall/1"},"b0kbv0":{"a":"recall","vg":"parasito-hydatidosis:e2/recall/1"},"1t46zin":{"a":"recall","vg":"parasito-hydatidosis:e4/recall/1"},"1hnszyk":{"a":"recall","vg":"parasito-hydatidosis:e4/recall/1"},"3vpvlr":{"a":"recall","vg":"parasito-hydatidosis:e4/recall/2"},"5jlgpv":{"a":"recall","vg":"parasito-hydatidosis:e6/recall/1"},"1mpoc93":{"a":"recall","vg":"parasito-hydatidosis:e6/recall/2"},"oexoll":{"a":"recall","vg":"parasito-hydatidosis:e7/recall/1"},"1r9ee1p":{"a":"recall","vg":"parasito-hydatidosis:e7/recall/2"},"1peapbv":{"a":"recall","vg":"parasito-hydatidosis:e8/recall/1"},"1aooazn":{"a":"recall","vg":"parasito-hydatidosis:e8/recall/2"},"1g6v4br":{"a":"recall","vg":"parasito-hydatidosis:e9/recall/1"},"1rmyvso":{"a":"recall","vg":"parasito-hydatidosis:e9/recall/2"},"pj1e1j":{"a":"recall","vg":"parasito-hydatidosis:e3/recall/1"}},"explRev":"0bca5bd44a1d"};
